def solve(n, edges):
    def find(x):
        while parent[x] != x:
            x = find(parent[x])
        return x

    parent = list(range(n))
    rank = [0] * n

    for u, v in edges:
        rootU, rootV = find(u), find(v)
        if rootU != rootV:
            if rank[rootU] > rank[rootV]:
                parent[rootV] = rootU
            elif rank[rootU] < rank[rootV]:
                parent[rootU] = rootV
            else:
                parent[rootV] = rootU
                rank[rootU] += 1

    return sum(parent[i] == i for i in range(n))
