from typing import List

def solve(n: int, edges: List[List[int]]) -> int:
    def find(parent: List[int], i: int) -> int:
        if parent[i] != i:
            parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent: List[int], rank: List[int], x: int, y: int) -> None:
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    parent = list(range(n))
    rank = [0] * n

    for u, v in edges:
        union(parent, rank, u, v)

    root_set = set()
    for i in range(n):
        root_set.add(find(parent, i))

    return len(root_set)
