def solve(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    components = 0
    visited = set()

    for node in range(n):
        if node not in visited:
            stack = [node]
            while stack:
                cur = stack.pop()
                if cur not in visited:
                    visited.add(cur)
                    for neighbor in graph[cur]:
                        if neighbor not in visited:
                            stack.append(neighbor)
            components += 1

    return components
