def solve(n, edges):
    class UnionFind:
        def __init__(self, n):
            self.parent = list(range(n))
            self.size = [1] * n
            self.n = n
            self.sets = n

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            rootX = self.find(x)
            rootY = self.find(y)
            if rootX != rootY:
                if self.size[rootX] < self.size[rootY]:
                    rootX, rootY = rootY, rootX
                self.parent[rootY] = rootX
                self.size[rootX] += self.size[rootY]
                self.sets -= 1

        def is_connected(self, x, y):
            return self.find(x) == self.find(y)

    uf = UnionFind(n)
    for u, v in edges:
        uf.union(u, v)

    return uf.sets
