                if neighbor not in visited:
                    stack.append(neighbor)

    visited = set()
    components = 0
    adj_list = {i: [] for i in range(n)}
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    for i in range(n):
        if i not in visited:
            dfs(i)
            components += 1

