        if rootX != rootY:
            if -parent[rootX] < -parent[rootY]:
                parent[rootX] += parent[rootY]
                parent[rootY] = rootX
            else:
                parent[rootY] += parent[rootX]
                parent[rootX] = rootY

    parent = [-1] * n
    for u, v in edges:
        union(u, v)

    components = sum(1 for p in parent if p < 0)
    return components
