def solve(nums):
    tortoise = nums[0]
    hare = nums[0])

    # Find the cells of the cycle Tortoise and Hare Algorithm
    def cycle(tortoise, hare):
        tortoise = nums[tortoise], hare = nums[nums[hare]];
        return (tortoise, hare)

    tortoise, hare = cycle(tortoise, hare)
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[hare]

    # Find the entrance to the cycle (the duplicate number)
    tortoise = nums[0]
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[hare]

    return hare
