def solve(nums):
    def solve(nums):
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def egcd(a, b):
            if a == 0:
                return b, 0, 1
            else:
                g, y, x = egcd(b % a, a)
                return g, x - (b // a) * y, y

        n = len(nums) - 1
        acc = 0
        for i, num in enumerate(nums):
            acc += i * num
            acc %= n + 1

        for num in nums:
            acc -= num
            acc += (n + 1 - num) * num
            acc %= n + 1

        g, x, y = egcd(acc, n + 1)
        return (x + n + 1) % (n + 1)
    return solve(nums)
