def solve(nums):
    def is_even(n):
        return n % 2 == 0

    def solve_r(arr, l, r):
        if l == r:
            return arr[l]
        mid = l + (r - l) // 2
        left = arr[l:mid + 1]
        right = arr[mid + 1:r + 1]
        left_sum = sum(left)
        right_sum = sum(right)
        if is_even(left_sum) and is_even(right_sum) or not is_even(left_sum) and not is_even(right_sum):
            return solve_r(arr, mid + 1, r)
        else:
            return solve_r(arr, l, mid) if is_even(left_sum) else solve_r(arr, mid + 1, r)

    return solve_r(nums, 0, len(nums) - 1)
