                    while _ and left:
                        if left[0] in wb:
                            _ -= 1
                            left.pop(0)
                            continue
                        break
                    else:
                        newdef[w].append(pos - len(left) + _)
                        break

        if not newdef:
            return -1

        альтернативные_позиции = []
        for w, l in newdef.items():
            l.sort(key=lambda x: (x in wb, x))
            if l[0] in wb:
                continue
            альтернативные_позиции.append((l[0], w))
            if len(альтернативные_позиции) > 1:
                break

        wb[w] = альтернативные_позиции[0][1]
        if not альтернативные_позиции:
            return -1
        return альтернативные_позиции[0][0]

    alphabet = set(needle)
    wb = defaultdict(lambda: '')
    _length = len(needle)
    while True:
        replacement = _find_replacement({}, wb, alphabet, _length)
        if replacement == -1:
            break
        _length = replacement + 1
    return wb['']
